(()=>{const added=[{"id":"daily-2026-10-22-r01-q01","module":"Git","type":"概念题","title":"reset、restore 与 revert：关键机制","prompt":"请解释reset、restore 与 revert的关键机制和适用边界。","promptMarkdown":"请解释reset、restore 与 revert的关键机制和适用边界。","answer":["restore 主要恢复文件或暂存内容；reset 可移动分支并按模式影响暂存区与工作区；revert 通过新提交反向应用既有改动，适合保留共享历史。"],"pitfalls":["常见协作回滚可用 revert 保留历史；是否重写历史须结合协作约定和明确授权。"],"follow":"已发布修复引入回归，怎么回退且让同事能继续拉取？","manual":true,"priority":false,"project":"通用","sourceDate":"2026-10-22","sourceRound":1,"sourceQuestion":1,"sourceRoundTitle":"reset、restore 与 revert","referenceUrl":"https://git-scm.com/docs","answerMarkdown":"### 参考答案\nrestore 主要恢复文件或暂存内容；reset 可移动分支并按模式影响暂存区与工作区；revert 通过新提交反向应用既有改动，适合保留共享历史。\n\n### 易错点\n常见协作回滚可用 revert 保留历史；是否重写历史须结合协作约定和明确授权。\n\n### 继续追问\n已发布修复引入回归，怎么回退且让同事能继续拉取？"},{"id":"daily-2026-10-22-r01-q02","module":"Git","type":"概念题","title":"公开分支回滚只能 reset --hard 再强推吗？","prompt":"公开分支回滚只能 reset --hard 再强推吗？","promptMarkdown":"公开分支回滚只能 reset --hard 再强推吗？","answer":["常见协作回滚可用 revert 保留历史；是否重写历史须结合协作约定和明确授权。"],"pitfalls":["常见协作回滚可用 revert 保留历史；是否重写历史须结合协作约定和明确授权。"],"follow":"已发布修复引入回归，怎么回退且让同事能继续拉取？","manual":true,"priority":false,"project":"通用","sourceDate":"2026-10-22","sourceRound":1,"sourceQuestion":2,"sourceRoundTitle":"reset、restore 与 revert","referenceUrl":"https://git-scm.com/docs","answerMarkdown":"### 参考答案\n常见协作回滚可用 revert 保留历史；是否重写历史须结合协作约定和明确授权。\n\n### 易错点\n常见协作回滚可用 revert 保留历史；是否重写历史须结合协作约定和明确授权。\n\n### 继续追问\n已发布修复引入回归，怎么回退且让同事能继续拉取？"},{"id":"daily-2026-10-22-r01-q03","module":"Git","type":"场景题","title":"已发布修复引入回归，怎么回退且让同事能继续拉取？","prompt":"已发布修复引入回归，怎么回退且让同事能继续拉取？","promptMarkdown":"已发布修复引入回归，怎么回退且让同事能继续拉取？","answer":["定位具体提交，评估依赖与合并提交情况，在修复分支生成反向提交并验证。"],"pitfalls":["常见协作回滚可用 revert 保留历史；是否重写历史须结合协作约定和明确授权。"],"follow":"已发布修复引入回归，怎么回退且让同事能继续拉取？","manual":true,"priority":false,"project":"通用","sourceDate":"2026-10-22","sourceRound":1,"sourceQuestion":3,"sourceRoundTitle":"reset、restore 与 revert","referenceUrl":"https://git-scm.com/docs","answerMarkdown":"### 参考答案\n定位具体提交，评估依赖与合并提交情况，在修复分支生成反向提交并验证。\n\n### 易错点\n常见协作回滚可用 revert 保留历史；是否重写历史须结合协作约定和明确授权。\n\n### 继续追问\n已发布修复引入回归，怎么回退且让同事能继续拉取？"},{"id":"daily-2026-10-22-r01-q04","module":"Git","type":"代码题","title":"reset、restore 与 revert：动手练习","prompt":"先只读确认目标提交与影响范围；反向提交练习仅在临时分支完成。","promptMarkdown":"先只读确认目标提交与影响范围；反向提交练习仅在临时分支完成。","answer":["restore 主要恢复文件或暂存内容；reset 可移动分支并按模式影响暂存区与工作区；revert 通过新提交反向应用既有改动，适合保留共享历史。"],"pitfalls":["常见协作回滚可用 revert 保留历史；是否重写历史须结合协作约定和明确授权。"],"follow":"已发布修复引入回归，怎么回退且让同事能继续拉取？","manual":true,"priority":false,"project":"通用","sourceDate":"2026-10-22","sourceRound":1,"sourceQuestion":4,"sourceRoundTitle":"reset、restore 与 revert","referenceUrl":"https://git-scm.com/docs","answerMarkdown":"### 参考答案\nrestore 主要恢复文件或暂存内容；reset 可移动分支并按模式影响暂存区与工作区；revert 通过新提交反向应用既有改动，适合保留共享历史。\n\n### 易错点\n常见协作回滚可用 revert 保留历史；是否重写历史须结合协作约定和明确授权。\n\n### 示例\n```bash\ngit show --stat bad_commit\ngit log --oneline -8\n# 在临时分支：git revert bad_commit\n```\n\n命令与配置用于隔离练习环境；先核对占位名称、权限、路径与工具版本。Docker 示例不代表已在你的服务中部署。\n\n### 继续追问\n已发布修复引入回归，怎么回退且让同事能继续拉取？"},{"id":"daily-2026-10-22-r01-q05","module":"Git","type":"场景题","title":"IM 数据库迁移与代码一起回退，有什么额外风险？","prompt":"IM 数据库迁移与代码一起回退，有什么额外风险？","promptMarkdown":"IM 数据库迁移与代码一起回退，有什么额外风险？","answer":["Git 只处理代码历史，不自动撤销数据库结构或数据变更；需要版本兼容、迁移回退或前向修复计划。"],"pitfalls":["常见协作回滚可用 revert 保留历史；是否重写历史须结合协作约定和明确授权。"],"follow":"已发布修复引入回归，怎么回退且让同事能继续拉取？","manual":true,"priority":false,"project":"IM","sourceDate":"2026-10-22","sourceRound":1,"sourceQuestion":5,"sourceRoundTitle":"reset、restore 与 revert","referenceUrl":"https://git-scm.com/docs","answerMarkdown":"### 参考答案\nGit 只处理代码历史，不自动撤销数据库结构或数据变更；需要版本兼容、迁移回退或前向修复计划。\n\n### 易错点\n常见协作回滚可用 revert 保留历史；是否重写历史须结合协作约定和明确授权。\n\n### 继续追问\n已发布修复引入回归，怎么回退且让同事能继续拉取？"},{"id":"daily-2026-10-22-r02-q01","module":"Docker","type":"概念题","title":"命名卷、绑定挂载与数据持久化：关键机制","prompt":"请解释命名卷、绑定挂载与数据持久化的关键机制和适用边界。","promptMarkdown":"请解释命名卷、绑定挂载与数据持久化的关键机制和适用边界。","answer":["volume 由 Docker 管理，bind mount 直接映射宿主路径；两者都能独立于容器可写层保存数据。持久化不等于备份或跨主机复制。"],"pitfalls":["持久卷仍可能随宿主故障或误删丢失，需要备份及恢复演练。"],"follow":"挂载后镜像内预置文件看不见了，如何解释？","manual":true,"priority":false,"project":"通用","sourceDate":"2026-10-22","sourceRound":2,"sourceQuestion":1,"sourceRoundTitle":"命名卷、绑定挂载与数据持久化","referenceUrl":"https://docs.docker.com/","answerMarkdown":"### 参考答案\nvolume 由 Docker 管理，bind mount 直接映射宿主路径；两者都能独立于容器可写层保存数据。持久化不等于备份或跨主机复制。\n\n### 易错点\n持久卷仍可能随宿主故障或误删丢失，需要备份及恢复演练。\n\n### 继续追问\n挂载后镜像内预置文件看不见了，如何解释？"},{"id":"daily-2026-10-22-r02-q02","module":"Docker","type":"概念题","title":"删容器后数据还在，就证明已有灾备了吗？","prompt":"删容器后数据还在，就证明已有灾备了吗？","promptMarkdown":"删容器后数据还在，就证明已有灾备了吗？","answer":["持久卷仍可能随宿主故障或误删丢失，需要备份及恢复演练。"],"pitfalls":["持久卷仍可能随宿主故障或误删丢失，需要备份及恢复演练。"],"follow":"挂载后镜像内预置文件看不见了，如何解释？","manual":true,"priority":false,"project":"通用","sourceDate":"2026-10-22","sourceRound":2,"sourceQuestion":2,"sourceRoundTitle":"命名卷、绑定挂载与数据持久化","referenceUrl":"https://docs.docker.com/","answerMarkdown":"### 参考答案\n持久卷仍可能随宿主故障或误删丢失，需要备份及恢复演练。\n\n### 易错点\n持久卷仍可能随宿主故障或误删丢失，需要备份及恢复演练。\n\n### 继续追问\n挂载后镜像内预置文件看不见了，如何解释？"},{"id":"daily-2026-10-22-r02-q03","module":"Docker","type":"场景题","title":"挂载后镜像内预置文件看不见了，如何解释？","prompt":"挂载后镜像内预置文件看不见了，如何解释？","promptMarkdown":"挂载后镜像内预置文件看不见了，如何解释？","answer":["挂载会遮蔽目标路径原有内容；区分 bind 与空卷初始化行为，核对 Mounts 和路径。"],"pitfalls":["持久卷仍可能随宿主故障或误删丢失，需要备份及恢复演练。"],"follow":"挂载后镜像内预置文件看不见了，如何解释？","manual":true,"priority":false,"project":"通用","sourceDate":"2026-10-22","sourceRound":2,"sourceQuestion":3,"sourceRoundTitle":"命名卷、绑定挂载与数据持久化","referenceUrl":"https://docs.docker.com/","answerMarkdown":"### 参考答案\n挂载会遮蔽目标路径原有内容；区分 bind 与空卷初始化行为，核对 Mounts 和路径。\n\n### 易错点\n持久卷仍可能随宿主故障或误删丢失，需要备份及恢复演练。\n\n### 继续追问\n挂载后镜像内预置文件看不见了，如何解释？"},{"id":"daily-2026-10-22-r02-q04","module":"Docker","type":"代码题","title":"命名卷、绑定挂载与数据持久化：动手练习","prompt":"只读检查测试容器的挂载信息与卷元数据。","promptMarkdown":"只读检查测试容器的挂载信息与卷元数据。","answer":["volume 由 Docker 管理，bind mount 直接映射宿主路径；两者都能独立于容器可写层保存数据。持久化不等于备份或跨主机复制。"],"pitfalls":["持久卷仍可能随宿主故障或误删丢失，需要备份及恢复演练。"],"follow":"挂载后镜像内预置文件看不见了，如何解释？","manual":true,"priority":false,"project":"通用","sourceDate":"2026-10-22","sourceRound":2,"sourceQuestion":4,"sourceRoundTitle":"命名卷、绑定挂载与数据持久化","referenceUrl":"https://docs.docker.com/","answerMarkdown":"### 参考答案\nvolume 由 Docker 管理，bind mount 直接映射宿主路径；两者都能独立于容器可写层保存数据。持久化不等于备份或跨主机复制。\n\n### 易错点\n持久卷仍可能随宿主故障或误删丢失，需要备份及恢复演练。\n\n### 示例\n```bash\ndocker inspect lab-app --format \"{{json .Mounts}}\"\ndocker volume inspect lab-data\n```\n\n命令与配置用于隔离练习环境；先核对占位名称、权限、路径与工具版本。Docker 示例不代表已在你的服务中部署。\n\n### 继续追问\n挂载后镜像内预置文件看不见了，如何解释？"},{"id":"daily-2026-10-22-r02-q05","module":"Docker","type":"场景题","title":"云盘 MySQL 和本地上传目录应该如何分开持久化？","prompt":"云盘 MySQL 和本地上传目录应该如何分开持久化？","promptMarkdown":"云盘 MySQL 和本地上传目录应该如何分开持久化？","answer":["分别明确数据库与文件内容的数据路径、权限、备份策略与一致性需求；不能只保留上传目录而遗漏元数据。"],"pitfalls":["持久卷仍可能随宿主故障或误删丢失，需要备份及恢复演练。"],"follow":"挂载后镜像内预置文件看不见了，如何解释？","manual":true,"priority":false,"project":"云盘","sourceDate":"2026-10-22","sourceRound":2,"sourceQuestion":5,"sourceRoundTitle":"命名卷、绑定挂载与数据持久化","referenceUrl":"https://docs.docker.com/","answerMarkdown":"### 参考答案\n分别明确数据库与文件内容的数据路径、权限、备份策略与一致性需求；不能只保留上传目录而遗漏元数据。\n\n### 易错点\n持久卷仍可能随宿主故障或误删丢失，需要备份及恢复演练。\n\n### 继续追问\n挂载后镜像内预置文件看不见了，如何解释？"},{"id":"daily-2026-10-22-r03-q01","module":"Linux","type":"概念题","title":"mmap、页缓存与文件持久化：关键机制","prompt":"请解释mmap、页缓存与文件持久化的关键机制和适用边界。","promptMarkdown":"请解释mmap、页缓存与文件持久化的关键机制和适用边界。","answer":["mmap 建立虚拟内存映射，访问可能触发缺页；共享映射与私有写时复制语义不同。写入可见和崩溃后持久不是同一保证。"],"pitfalls":["缺页仍可能触发磁盘读取，内存访问也受页缓存、映射规模及回收影响。"],"follow":"大文件映射后 RSS 不断增长就一定泄漏吗？","manual":true,"priority":false,"project":"通用","sourceDate":"2026-10-22","sourceRound":3,"sourceQuestion":1,"sourceRoundTitle":"mmap、页缓存与文件持久化","referenceUrl":"https://man7.org/linux/man-pages/","answerMarkdown":"### 参考答案\nmmap 建立虚拟内存映射，访问可能触发缺页；共享映射与私有写时复制语义不同。写入可见和崩溃后持久不是同一保证。\n\n### 易错点\n缺页仍可能触发磁盘读取，内存访问也受页缓存、映射规模及回收影响。\n\n### 继续追问\n大文件映射后 RSS 不断增长就一定泄漏吗？"},{"id":"daily-2026-10-22-r03-q02","module":"Linux","type":"概念题","title":"mmap 不调用 read 就没有 IO 或缺页开销吗？","prompt":"mmap 不调用 read 就没有 IO 或缺页开销吗？","promptMarkdown":"mmap 不调用 read 就没有 IO 或缺页开销吗？","answer":["缺页仍可能触发磁盘读取，内存访问也受页缓存、映射规模及回收影响。"],"pitfalls":["缺页仍可能触发磁盘读取，内存访问也受页缓存、映射规模及回收影响。"],"follow":"大文件映射后 RSS 不断增长就一定泄漏吗？","manual":true,"priority":false,"project":"通用","sourceDate":"2026-10-22","sourceRound":3,"sourceQuestion":2,"sourceRoundTitle":"mmap、页缓存与文件持久化","referenceUrl":"https://man7.org/linux/man-pages/","answerMarkdown":"### 参考答案\n缺页仍可能触发磁盘读取，内存访问也受页缓存、映射规模及回收影响。\n\n### 易错点\n缺页仍可能触发磁盘读取，内存访问也受页缓存、映射规模及回收影响。\n\n### 继续追问\n大文件映射后 RSS 不断增长就一定泄漏吗？"},{"id":"daily-2026-10-22-r03-q03","module":"Linux","type":"场景题","title":"大文件映射后 RSS 不断增长就一定泄漏吗？","prompt":"大文件映射后 RSS 不断增长就一定泄漏吗？","promptMarkdown":"大文件映射后 RSS 不断增长就一定泄漏吗？","answer":["区分匿名与文件映射、共享页和页缓存，结合 smaps_rollup 与访问模式分析。"],"pitfalls":["缺页仍可能触发磁盘读取，内存访问也受页缓存、映射规模及回收影响。"],"follow":"大文件映射后 RSS 不断增长就一定泄漏吗？","manual":true,"priority":false,"project":"通用","sourceDate":"2026-10-22","sourceRound":3,"sourceQuestion":3,"sourceRoundTitle":"mmap、页缓存与文件持久化","referenceUrl":"https://man7.org/linux/man-pages/","answerMarkdown":"### 参考答案\n区分匿名与文件映射、共享页和页缓存，结合 smaps_rollup 与访问模式分析。\n\n### 易错点\n缺页仍可能触发磁盘读取，内存访问也受页缓存、映射规模及回收影响。\n\n### 继续追问\n大文件映射后 RSS 不断增长就一定泄漏吗？"},{"id":"daily-2026-10-22-r03-q04","module":"Linux","type":"代码题","title":"mmap、页缓存与文件持久化：动手练习","prompt":"对测试 PID 查看映射类别和 RSS 组成，解释 VIRT 与 RSS 差别。","promptMarkdown":"对测试 PID 查看映射类别和 RSS 组成，解释 VIRT 与 RSS 差别。","answer":["mmap 建立虚拟内存映射，访问可能触发缺页；共享映射与私有写时复制语义不同。写入可见和崩溃后持久不是同一保证。"],"pitfalls":["缺页仍可能触发磁盘读取，内存访问也受页缓存、映射规模及回收影响。"],"follow":"大文件映射后 RSS 不断增长就一定泄漏吗？","manual":true,"priority":false,"project":"通用","sourceDate":"2026-10-22","sourceRound":3,"sourceQuestion":4,"sourceRoundTitle":"mmap、页缓存与文件持久化","referenceUrl":"https://man7.org/linux/man-pages/","answerMarkdown":"### 参考答案\nmmap 建立虚拟内存映射，访问可能触发缺页；共享映射与私有写时复制语义不同。写入可见和崩溃后持久不是同一保证。\n\n### 易错点\n缺页仍可能触发磁盘读取，内存访问也受页缓存、映射规模及回收影响。\n\n### 示例\n```bash\ncat /proc/1234/smaps_rollup\ncat /proc/1234/maps # 1234 替换为测试 PID\n```\n\n命令与配置用于隔离练习环境；先核对占位名称、权限、路径与工具版本。Docker 示例不代表已在你的服务中部署。\n\n### 继续追问\n大文件映射后 RSS 不断增长就一定泄漏吗？"},{"id":"daily-2026-10-22-r03-q05","module":"Linux","type":"场景题","title":"云盘使用 mmap 下载是否一定优于 read 循环？","prompt":"云盘使用 mmap 下载是否一定优于 read 循环？","promptMarkdown":"云盘使用 mmap 下载是否一定优于 read 循环？","answer":["要比较文件大小、并发、缺页、错误处理和生命周期成本；不以 API 名称宣称零拷贝或固定性能提升。"],"pitfalls":["缺页仍可能触发磁盘读取，内存访问也受页缓存、映射规模及回收影响。"],"follow":"大文件映射后 RSS 不断增长就一定泄漏吗？","manual":true,"priority":false,"project":"云盘","sourceDate":"2026-10-22","sourceRound":3,"sourceQuestion":5,"sourceRoundTitle":"mmap、页缓存与文件持久化","referenceUrl":"https://man7.org/linux/man-pages/","answerMarkdown":"### 参考答案\n要比较文件大小、并发、缺页、错误处理和生命周期成本；不以 API 名称宣称零拷贝或固定性能提升。\n\n### 易错点\n缺页仍可能触发磁盘读取，内存访问也受页缓存、映射规模及回收影响。\n\n### 继续追问\n大文件映射后 RSS 不断增长就一定泄漏吗？"},{"id":"daily-2026-10-22-r04-q01","module":"Linux","type":"概念题","title":"信号处理与安全退出：关键机制","prompt":"请解释信号处理与安全退出的关键机制和适用边界。","promptMarkdown":"请解释信号处理与安全退出的关键机制和适用边界。","answer":["异步信号处理器只能调用适合该上下文的安全操作。常见做法是设置 sig_atomic_t 标志或通知事件循环，在正常执行流中完成复杂清理。"],"pitfalls":["可能重入非安全函数或与被中断线程互锁；应把锁、分配和复杂 IO 移到正常上下文。"],"follow":"服务退出时偶发死锁，如何审查信号路径？","manual":true,"priority":false,"project":"通用","sourceDate":"2026-10-22","sourceRound":4,"sourceQuestion":1,"sourceRoundTitle":"信号处理与安全退出","referenceUrl":"https://man7.org/linux/man-pages/","answerMarkdown":"### 参考答案\n异步信号处理器只能调用适合该上下文的安全操作。常见做法是设置 sig_atomic_t 标志或通知事件循环，在正常执行流中完成复杂清理。\n\n### 易错点\n可能重入非安全函数或与被中断线程互锁；应把锁、分配和复杂 IO 移到正常上下文。\n\n### 继续追问\n服务退出时偶发死锁，如何审查信号路径？"},{"id":"daily-2026-10-22-r04-q02","module":"Linux","type":"概念题","title":"SIGTERM 处理器里能直接加 mutex 写复杂日志吗？","prompt":"SIGTERM 处理器里能直接加 mutex 写复杂日志吗？","promptMarkdown":"SIGTERM 处理器里能直接加 mutex 写复杂日志吗？","answer":["可能重入非安全函数或与被中断线程互锁；应把锁、分配和复杂 IO 移到正常上下文。"],"pitfalls":["可能重入非安全函数或与被中断线程互锁；应把锁、分配和复杂 IO 移到正常上下文。"],"follow":"服务退出时偶发死锁，如何审查信号路径？","manual":true,"priority":false,"project":"通用","sourceDate":"2026-10-22","sourceRound":4,"sourceQuestion":2,"sourceRoundTitle":"信号处理与安全退出","referenceUrl":"https://man7.org/linux/man-pages/","answerMarkdown":"### 参考答案\n可能重入非安全函数或与被中断线程互锁；应把锁、分配和复杂 IO 移到正常上下文。\n\n### 易错点\n可能重入非安全函数或与被中断线程互锁；应把锁、分配和复杂 IO 移到正常上下文。\n\n### 继续追问\n服务退出时偶发死锁，如何审查信号路径？"},{"id":"daily-2026-10-22-r04-q03","module":"Linux","type":"场景题","title":"服务退出时偶发死锁，如何审查信号路径？","prompt":"服务退出时偶发死锁，如何审查信号路径？","promptMarkdown":"服务退出时偶发死锁，如何审查信号路径？","answer":["确认信号打断位置、处理器调用链与主循环唤醒机制，再核对线程停止和 join 顺序。"],"pitfalls":["可能重入非安全函数或与被中断线程互锁；应把锁、分配和复杂 IO 移到正常上下文。"],"follow":"服务退出时偶发死锁，如何审查信号路径？","manual":true,"priority":false,"project":"通用","sourceDate":"2026-10-22","sourceRound":4,"sourceQuestion":3,"sourceRoundTitle":"信号处理与安全退出","referenceUrl":"https://man7.org/linux/man-pages/","answerMarkdown":"### 参考答案\n确认信号打断位置、处理器调用链与主循环唤醒机制，再核对线程停止和 join 顺序。\n\n### 易错点\n可能重入非安全函数或与被中断线程互锁；应把锁、分配和复杂 IO 移到正常上下文。\n\n### 继续追问\n服务退出时偶发死锁，如何审查信号路径？"},{"id":"daily-2026-10-22-r04-q04","module":"Linux","type":"代码题","title":"信号处理与安全退出：动手练习","prompt":"说明最小信号标记程序的边界，不把标记当成完整优雅退出。","promptMarkdown":"说明最小信号标记程序的边界，不把标记当成完整优雅退出。","answer":["异步信号处理器只能调用适合该上下文的安全操作。常见做法是设置 sig_atomic_t 标志或通知事件循环，在正常执行流中完成复杂清理。"],"pitfalls":["可能重入非安全函数或与被中断线程互锁；应把锁、分配和复杂 IO 移到正常上下文。"],"follow":"服务退出时偶发死锁，如何审查信号路径？","manual":true,"priority":false,"project":"通用","sourceDate":"2026-10-22","sourceRound":4,"sourceQuestion":4,"sourceRoundTitle":"信号处理与安全退出","referenceUrl":"https://man7.org/linux/man-pages/","answerMarkdown":"### 参考答案\n异步信号处理器只能调用适合该上下文的安全操作。常见做法是设置 sig_atomic_t 标志或通知事件循环，在正常执行流中完成复杂清理。\n\n### 易错点\n可能重入非安全函数或与被中断线程互锁；应把锁、分配和复杂 IO 移到正常上下文。\n\n### 示例\n```c\n#include <signal.h>\nstatic volatile sig_atomic_t stopping = 0;\nstatic void on_term(int sig) { (void)sig; stopping = 1; }\n/* 用 sigaction 安装；主循环观察标记并完成资源清理。 */\n```\n\n命令与配置用于隔离练习环境；先核对占位名称、权限、路径与工具版本。Docker 示例不代表已在你的服务中部署。\n\n### 继续追问\n服务退出时偶发死锁，如何审查信号路径？"},{"id":"daily-2026-10-22-r04-q05","module":"Linux","type":"场景题","title":"IM 收到 SIGTERM 后应该按什么顺序关闭？","prompt":"IM 收到 SIGTERM 后应该按什么顺序关闭？","promptMarkdown":"IM 收到 SIGTERM 后应该按什么顺序关闭？","answer":["停止新接入，给正在处理的工作明确截止时间，停止订阅与工作线程，再释放依赖；是否落实需用真实退出路径和测试核对。"],"pitfalls":["可能重入非安全函数或与被中断线程互锁；应把锁、分配和复杂 IO 移到正常上下文。"],"follow":"服务退出时偶发死锁，如何审查信号路径？","manual":true,"priority":false,"project":"IM","sourceDate":"2026-10-22","sourceRound":4,"sourceQuestion":5,"sourceRoundTitle":"信号处理与安全退出","referenceUrl":"https://man7.org/linux/man-pages/","answerMarkdown":"### 参考答案\n停止新接入，给正在处理的工作明确截止时间，停止订阅与工作线程，再释放依赖；是否落实需用真实退出路径和测试核对。\n\n### 易错点\n可能重入非安全函数或与被中断线程互锁；应把锁、分配和复杂 IO 移到正常上下文。\n\n### 继续追问\n服务退出时偶发死锁，如何审查信号路径？"},{"id":"daily-2026-10-22-r05-q01","module":"Qt","type":"概念题","title":"QNetworkAccessManager 与异步完成：关键机制","prompt":"请解释QNetworkAccessManager 与异步完成的关键机制和适用边界。","promptMarkdown":"请解释QNetworkAccessManager 与异步完成的关键机制和适用边界。","answer":["QNetworkAccessManager 发起异步请求并返回 QNetworkReply；finished 表示请求处理结束，仍需判断网络错误、HTTP 状态及业务响应，然后清理 reply。"],"pitfalls":["错误请求同样会结束；应分别检查 reply error、状态码和 JSON 业务字段。"],"follow":"登录网络回调完成但界面误报成功，如何修复？","manual":true,"priority":false,"project":"通用","sourceDate":"2026-10-22","sourceRound":5,"sourceQuestion":1,"sourceRoundTitle":"QNetworkAccessManager 与异步完成","referenceUrl":"https://doc.qt.io/qt-6/","answerMarkdown":"### 参考答案\nQNetworkAccessManager 发起异步请求并返回 QNetworkReply；finished 表示请求处理结束，仍需判断网络错误、HTTP 状态及业务响应，然后清理 reply。\n\n### 易错点\n错误请求同样会结束；应分别检查 reply error、状态码和 JSON 业务字段。\n\n### 继续追问\n登录网络回调完成但界面误报成功，如何修复？"},{"id":"daily-2026-10-22-r05-q02","module":"Qt","type":"概念题","title":"finished 触发就一定 HTTP 200 且业务成功吗？","prompt":"finished 触发就一定 HTTP 200 且业务成功吗？","promptMarkdown":"finished 触发就一定 HTTP 200 且业务成功吗？","answer":["错误请求同样会结束；应分别检查 reply error、状态码和 JSON 业务字段。"],"pitfalls":["错误请求同样会结束；应分别检查 reply error、状态码和 JSON 业务字段。"],"follow":"登录网络回调完成但界面误报成功，如何修复？","manual":true,"priority":false,"project":"通用","sourceDate":"2026-10-22","sourceRound":5,"sourceQuestion":2,"sourceRoundTitle":"QNetworkAccessManager 与异步完成","referenceUrl":"https://doc.qt.io/qt-6/","answerMarkdown":"### 参考答案\n错误请求同样会结束；应分别检查 reply error、状态码和 JSON 业务字段。\n\n### 易错点\n错误请求同样会结束；应分别检查 reply error、状态码和 JSON 业务字段。\n\n### 继续追问\n登录网络回调完成但界面误报成功，如何修复？"},{"id":"daily-2026-10-22-r05-q03","module":"Qt","type":"场景题","title":"登录网络回调完成但界面误报成功，如何修复？","prompt":"登录网络回调完成但界面误报成功，如何修复？","promptMarkdown":"登录网络回调完成但界面误报成功，如何修复？","answer":["把传输错误、HTTP 非成功、JSON 解析失败和业务拒绝分层处理，不只判断是否收到回调。"],"pitfalls":["错误请求同样会结束；应分别检查 reply error、状态码和 JSON 业务字段。"],"follow":"登录网络回调完成但界面误报成功，如何修复？","manual":true,"priority":false,"project":"通用","sourceDate":"2026-10-22","sourceRound":5,"sourceQuestion":3,"sourceRoundTitle":"QNetworkAccessManager 与异步完成","referenceUrl":"https://doc.qt.io/qt-6/","answerMarkdown":"### 参考答案\n把传输错误、HTTP 非成功、JSON 解析失败和业务拒绝分层处理，不只判断是否收到回调。\n\n### 易错点\n错误请求同样会结束；应分别检查 reply error、状态码和 JSON 业务字段。\n\n### 继续追问\n登录网络回调完成但界面误报成功，如何修复？"},{"id":"daily-2026-10-22-r05-q04","module":"Qt","type":"代码题","title":"QNetworkAccessManager 与异步完成：动手练习","prompt":"阅读完成处理骨架，补充业务 JSON 校验与 UI 状态恢复。","promptMarkdown":"阅读完成处理骨架，补充业务 JSON 校验与 UI 状态恢复。","answer":["QNetworkAccessManager 发起异步请求并返回 QNetworkReply；finished 表示请求处理结束，仍需判断网络错误、HTTP 状态及业务响应，然后清理 reply。"],"pitfalls":["错误请求同样会结束；应分别检查 reply error、状态码和 JSON 业务字段。"],"follow":"登录网络回调完成但界面误报成功，如何修复？","manual":true,"priority":false,"project":"通用","sourceDate":"2026-10-22","sourceRound":5,"sourceQuestion":4,"sourceRoundTitle":"QNetworkAccessManager 与异步完成","referenceUrl":"https://doc.qt.io/qt-6/","answerMarkdown":"### 参考答案\nQNetworkAccessManager 发起异步请求并返回 QNetworkReply；finished 表示请求处理结束，仍需判断网络错误、HTTP 状态及业务响应，然后清理 reply。\n\n### 易错点\n错误请求同样会结束；应分别检查 reply error、状态码和 JSON 业务字段。\n\n### 示例\n```cpp-qt\nconnect(reply, &QNetworkReply::finished, this, [reply] {\n    const auto err = reply->error();\n    const int status = reply->attribute(QNetworkRequest::HttpStatusCodeAttribute).toInt();\n    const QByteArray body = reply->readAll();\n    // 分别处理 err、status 和 body 中的业务结果\n    reply->deleteLater();\n});\n```\n\n命令与配置用于隔离练习环境；先核对占位名称、权限、路径与工具版本。Docker 示例不代表已在你的服务中部署。\n\n### 继续追问\n登录网络回调完成但界面误报成功，如何修复？"},{"id":"daily-2026-10-22-r05-q05","module":"Qt","type":"场景题","title":"云盘登录失败后为什么不能保留上次的成功状态？","prompt":"云盘登录失败后为什么不能保留上次的成功状态？","promptMarkdown":"云盘登录失败后为什么不能保留上次的成功状态？","answer":["清理界面和请求状态时要区分当前请求与旧结果，成功后才更新可信会话；不要把错误正文或完整 Token 直接写日志。"],"pitfalls":["错误请求同样会结束；应分别检查 reply error、状态码和 JSON 业务字段。"],"follow":"登录网络回调完成但界面误报成功，如何修复？","manual":true,"priority":false,"project":"云盘","sourceDate":"2026-10-22","sourceRound":5,"sourceQuestion":5,"sourceRoundTitle":"QNetworkAccessManager 与异步完成","referenceUrl":"https://doc.qt.io/qt-6/","answerMarkdown":"### 参考答案\n清理界面和请求状态时要区分当前请求与旧结果，成功后才更新可信会话；不要把错误正文或完整 Token 直接写日志。\n\n### 易错点\n错误请求同样会结束；应分别检查 reply error、状态码和 JSON 业务字段。\n\n### 继续追问\n登录网络回调完成但界面误报成功，如何修复？"},{"id":"daily-2026-10-22-r06-q01","module":"C++","type":"概念题","title":"string_view 的借用生命周期：关键机制","prompt":"请解释string_view 的借用生命周期的关键机制和适用边界。","promptMarkdown":"请解释string_view 的借用生命周期的关键机制和适用边界。","answer":["string_view 不拥有字符内存，只保存地址与长度。原字符串销毁、移动或修改导致存储变化时，视图可能失效；它也不保证以零结尾。"],"pitfalls":["局部字符串析构后视图悬空；应返回拥有数据的 string 或保证外部存储寿命。"],"follow":"异步日志偶发乱码，为什么怀疑 string_view？","manual":true,"priority":false,"project":"通用","sourceDate":"2026-10-22","sourceRound":6,"sourceQuestion":1,"sourceRoundTitle":"string_view 的借用生命周期","referenceUrl":"https://eel.is/c++draft/","answerMarkdown":"### 参考答案\nstring_view 不拥有字符内存，只保存地址与长度。原字符串销毁、移动或修改导致存储变化时，视图可能失效；它也不保证以零结尾。\n\n### 易错点\n局部字符串析构后视图悬空；应返回拥有数据的 string 或保证外部存储寿命。\n\n### 继续追问\n异步日志偶发乱码，为什么怀疑 string_view？"},{"id":"daily-2026-10-22-r06-q02","module":"C++","type":"概念题","title":"函数返回局部 string 的 string_view 安全吗？","prompt":"函数返回局部 string 的 string_view 安全吗？","promptMarkdown":"函数返回局部 string 的 string_view 安全吗？","answer":["局部字符串析构后视图悬空；应返回拥有数据的 string 或保证外部存储寿命。"],"pitfalls":["局部字符串析构后视图悬空；应返回拥有数据的 string 或保证外部存储寿命。"],"follow":"异步日志偶发乱码，为什么怀疑 string_view？","manual":true,"priority":false,"project":"通用","sourceDate":"2026-10-22","sourceRound":6,"sourceQuestion":2,"sourceRoundTitle":"string_view 的借用生命周期","referenceUrl":"https://eel.is/c++draft/","answerMarkdown":"### 参考答案\n局部字符串析构后视图悬空；应返回拥有数据的 string 或保证外部存储寿命。\n\n### 易错点\n局部字符串析构后视图悬空；应返回拥有数据的 string 或保证外部存储寿命。\n\n### 继续追问\n异步日志偶发乱码，为什么怀疑 string_view？"},{"id":"daily-2026-10-22-r06-q03","module":"C++","type":"场景题","title":"异步日志偶发乱码，为什么怀疑 string_view？","prompt":"异步日志偶发乱码，为什么怀疑 string_view？","promptMarkdown":"异步日志偶发乱码，为什么怀疑 string_view？","answer":["检查队列是否保存借用视图，以及生产者返回后原缓冲是否销毁或复用。"],"pitfalls":["局部字符串析构后视图悬空；应返回拥有数据的 string 或保证外部存储寿命。"],"follow":"异步日志偶发乱码，为什么怀疑 string_view？","manual":true,"priority":false,"project":"通用","sourceDate":"2026-10-22","sourceRound":6,"sourceQuestion":3,"sourceRoundTitle":"string_view 的借用生命周期","referenceUrl":"https://eel.is/c++draft/","answerMarkdown":"### 参考答案\n检查队列是否保存借用视图，以及生产者返回后原缓冲是否销毁或复用。\n\n### 易错点\n局部字符串析构后视图悬空；应返回拥有数据的 string 或保证外部存储寿命。\n\n### 继续追问\n异步日志偶发乱码，为什么怀疑 string_view？"},{"id":"daily-2026-10-22-r06-q04","module":"C++","type":"代码题","title":"string_view 的借用生命周期：动手练习","prompt":"对拥有稳定存储的字符串取视图，在存储销毁前完成访问。","promptMarkdown":"对拥有稳定存储的字符串取视图，在存储销毁前完成访问。","answer":["string_view 不拥有字符内存，只保存地址与长度。原字符串销毁、移动或修改导致存储变化时，视图可能失效；它也不保证以零结尾。"],"pitfalls":["局部字符串析构后视图悬空；应返回拥有数据的 string 或保证外部存储寿命。"],"follow":"异步日志偶发乱码，为什么怀疑 string_view？","manual":true,"priority":false,"project":"通用","sourceDate":"2026-10-22","sourceRound":6,"sourceQuestion":4,"sourceRoundTitle":"string_view 的借用生命周期","referenceUrl":"https://eel.is/c++draft/","answerMarkdown":"### 参考答案\nstring_view 不拥有字符内存，只保存地址与长度。原字符串销毁、移动或修改导致存储变化时，视图可能失效；它也不保证以零结尾。\n\n### 易错点\n局部字符串析构后视图悬空；应返回拥有数据的 string 或保证外部存储寿命。\n\n### 示例\n```cpp\n#include <cassert>\n#include <string>\n#include <string_view>\nint main(){std::string owned=\"file.txt\";std::string_view v(owned);assert(v.substr(0,4)==\"file\");}\n```\n\n此为独立 C++17 练习程序，验证记录见当日文件。\n\n### 继续追问\n异步日志偶发乱码，为什么怀疑 string_view？"},{"id":"daily-2026-10-22-r06-q05","module":"C++","type":"场景题","title":"云盘解析上传头后把视图保存到任务队列需要注意什么？","prompt":"云盘解析上传头后把视图保存到任务队列需要注意什么？","promptMarkdown":"云盘解析上传头后把视图保存到任务队列需要注意什么？","answer":["请求缓冲会在请求结束后释放，跨异步任务应复制必要字段或一起转移拥有缓冲的对象，不能只复制视图结构。"],"pitfalls":["局部字符串析构后视图悬空；应返回拥有数据的 string 或保证外部存储寿命。"],"follow":"异步日志偶发乱码，为什么怀疑 string_view？","manual":true,"priority":false,"project":"云盘","sourceDate":"2026-10-22","sourceRound":6,"sourceQuestion":5,"sourceRoundTitle":"string_view 的借用生命周期","referenceUrl":"https://eel.is/c++draft/","answerMarkdown":"### 参考答案\n请求缓冲会在请求结束后释放，跨异步任务应复制必要字段或一起转移拥有缓冲的对象，不能只复制视图结构。\n\n### 易错点\n局部字符串析构后视图悬空；应返回拥有数据的 string 或保证外部存储寿命。\n\n### 继续追问\n异步日志偶发乱码，为什么怀疑 string_view？"},{"id":"daily-2026-10-22-r07-q01","module":"TCP/HTTP","type":"概念题","title":"TLS 主机名验证与证书链：关键机制","prompt":"请解释TLS 主机名验证与证书链的关键机制和适用边界。","promptMarkdown":"请解释TLS 主机名验证与证书链的关键机制和适用边界。","answer":["TLS 加密还需要校验证书信任链和目标主机名。域名、SNI、系统时间、证书期限及代理都可能影响握手和身份验证。"],"pitfalls":["只是绕过了重要校验；应定位信任链、主机名或代理证书问题，而非把跳过校验当修复。"],"follow":"手机访问 HTTPS 失败而电脑正常，怎么分层检查？","manual":true,"priority":false,"project":"通用","sourceDate":"2026-10-22","sourceRound":7,"sourceQuestion":1,"sourceRoundTitle":"TLS 主机名验证与证书链","referenceUrl":"https://www.rfc-editor.org/rfc/rfc9110","answerMarkdown":"### 参考答案\nTLS 加密还需要校验证书信任链和目标主机名。域名、SNI、系统时间、证书期限及代理都可能影响握手和身份验证。\n\n### 易错点\n只是绕过了重要校验；应定位信任链、主机名或代理证书问题，而非把跳过校验当修复。\n\n### 继续追问\n手机访问 HTTPS 失败而电脑正常，怎么分层检查？"},{"id":"daily-2026-10-22-r07-q02","module":"TCP/HTTP","type":"概念题","title":"关闭证书验证后能连上就证明服务器安全了吗？","prompt":"关闭证书验证后能连上就证明服务器安全了吗？","promptMarkdown":"关闭证书验证后能连上就证明服务器安全了吗？","answer":["只是绕过了重要校验；应定位信任链、主机名或代理证书问题，而非把跳过校验当修复。"],"pitfalls":["只是绕过了重要校验；应定位信任链、主机名或代理证书问题，而非把跳过校验当修复。"],"follow":"手机访问 HTTPS 失败而电脑正常，怎么分层检查？","manual":true,"priority":false,"project":"通用","sourceDate":"2026-10-22","sourceRound":7,"sourceQuestion":2,"sourceRoundTitle":"TLS 主机名验证与证书链","referenceUrl":"https://www.rfc-editor.org/rfc/rfc9110","answerMarkdown":"### 参考答案\n只是绕过了重要校验；应定位信任链、主机名或代理证书问题，而非把跳过校验当修复。\n\n### 易错点\n只是绕过了重要校验；应定位信任链、主机名或代理证书问题，而非把跳过校验当修复。\n\n### 继续追问\n手机访问 HTTPS 失败而电脑正常，怎么分层检查？"},{"id":"daily-2026-10-22-r07-q03","module":"TCP/HTTP","type":"场景题","title":"手机访问 HTTPS 失败而电脑正常，怎么分层检查？","prompt":"手机访问 HTTPS 失败而电脑正常，怎么分层检查？","promptMarkdown":"手机访问 HTTPS 失败而电脑正常，怎么分层检查？","answer":["比较 DNS、系统时间、信任根、代理与网络路径，保留错误码及证书信息，不传出凭证。"],"pitfalls":["只是绕过了重要校验；应定位信任链、主机名或代理证书问题，而非把跳过校验当修复。"],"follow":"手机访问 HTTPS 失败而电脑正常，怎么分层检查？","manual":true,"priority":false,"project":"通用","sourceDate":"2026-10-22","sourceRound":7,"sourceQuestion":3,"sourceRoundTitle":"TLS 主机名验证与证书链","referenceUrl":"https://www.rfc-editor.org/rfc/rfc9110","answerMarkdown":"### 参考答案\n比较 DNS、系统时间、信任根、代理与网络路径，保留错误码及证书信息，不传出凭证。\n\n### 易错点\n只是绕过了重要校验；应定位信任链、主机名或代理证书问题，而非把跳过校验当修复。\n\n### 继续追问\n手机访问 HTTPS 失败而电脑正常，怎么分层检查？"},{"id":"daily-2026-10-22-r07-q04","module":"TCP/HTTP","type":"代码题","title":"TLS 主机名验证与证书链：动手练习","prompt":"只读检查目标证书链与主机名，示例域名替换为实际测试站。","promptMarkdown":"只读检查目标证书链与主机名，示例域名替换为实际测试站。","answer":["TLS 加密还需要校验证书信任链和目标主机名。域名、SNI、系统时间、证书期限及代理都可能影响握手和身份验证。"],"pitfalls":["只是绕过了重要校验；应定位信任链、主机名或代理证书问题，而非把跳过校验当修复。"],"follow":"手机访问 HTTPS 失败而电脑正常，怎么分层检查？","manual":true,"priority":false,"project":"通用","sourceDate":"2026-10-22","sourceRound":7,"sourceQuestion":4,"sourceRoundTitle":"TLS 主机名验证与证书链","referenceUrl":"https://www.rfc-editor.org/rfc/rfc9110","answerMarkdown":"### 参考答案\nTLS 加密还需要校验证书信任链和目标主机名。域名、SNI、系统时间、证书期限及代理都可能影响握手和身份验证。\n\n### 易错点\n只是绕过了重要校验；应定位信任链、主机名或代理证书问题，而非把跳过校验当修复。\n\n### 示例\n```bash\nopenssl s_client -connect example.com:443 -servername example.com -verify_hostname example.com -verify_return_error </dev/null\n```\n\n命令与配置用于隔离练习环境；先核对占位名称、权限、路径与工具版本。Docker 示例不代表已在你的服务中部署。\n\n### 继续追问\n手机访问 HTTPS 失败而电脑正常，怎么分层检查？"},{"id":"daily-2026-10-22-r07-q05","module":"TCP/HTTP","type":"场景题","title":"IM 客户端从 HTTP 改为 HTTPS/WSS 后需验证什么？","prompt":"IM 客户端从 HTTP 改为 HTTPS/WSS 后需验证什么？","promptMarkdown":"IM 客户端从 HTTP 改为 HTTPS/WSS 后需验证什么？","answer":["检查证书信任与域名、混合内容、反向代理升级路径、Token 传输和错误提示；连接成功不代表旧会话撤销与权限逻辑自动改变。"],"pitfalls":["只是绕过了重要校验；应定位信任链、主机名或代理证书问题，而非把跳过校验当修复。"],"follow":"手机访问 HTTPS 失败而电脑正常，怎么分层检查？","manual":true,"priority":false,"project":"IM","sourceDate":"2026-10-22","sourceRound":7,"sourceQuestion":5,"sourceRoundTitle":"TLS 主机名验证与证书链","referenceUrl":"https://www.rfc-editor.org/rfc/rfc9110","answerMarkdown":"### 参考答案\n检查证书信任与域名、混合内容、反向代理升级路径、Token 传输和错误提示；连接成功不代表旧会话撤销与权限逻辑自动改变。\n\n### 易错点\n只是绕过了重要校验；应定位信任链、主机名或代理证书问题，而非把跳过校验当修复。\n\n### 继续追问\n手机访问 HTTPS 失败而电脑正常，怎么分层检查？"},{"id":"daily-2026-10-22-r08-q01","module":"MySQL","type":"概念题","title":"读视图与长事务风险：关键机制","prompt":"请解释读视图与长事务风险的关键机制和适用边界。","promptMarkdown":"请解释读视图与长事务风险的关键机制和适用边界。","answer":["InnoDB 一致性读使用读视图决定版本可见性；隔离级别和语句类型影响视图使用。长事务可能拖延旧版本回收并增加历史版本负担。"],"pitfalls":["普通一致性读和当前读行为不同，不能把 SELECT FOR UPDATE 等同于普通快照读。"],"follow":"用户翻页时保持事务很久有什么问题？","manual":true,"priority":false,"project":"通用","sourceDate":"2026-10-22","sourceRound":8,"sourceQuestion":1,"sourceRoundTitle":"读视图与长事务风险","referenceUrl":"https://dev.mysql.com/doc/refman/8.4/en/","answerMarkdown":"### 参考答案\nInnoDB 一致性读使用读视图决定版本可见性；隔离级别和语句类型影响视图使用。长事务可能拖延旧版本回收并增加历史版本负担。\n\n### 易错点\n普通一致性读和当前读行为不同，不能把 SELECT FOR UPDATE 等同于普通快照读。\n\n### 继续追问\n用户翻页时保持事务很久有什么问题？"},{"id":"daily-2026-10-22-r08-q02","module":"MySQL","type":"概念题","title":"REPEATABLE READ 下所有查询都读同一个快照吗？","prompt":"REPEATABLE READ 下所有查询都读同一个快照吗？","promptMarkdown":"REPEATABLE READ 下所有查询都读同一个快照吗？","answer":["普通一致性读和当前读行为不同，不能把 SELECT FOR UPDATE 等同于普通快照读。"],"pitfalls":["普通一致性读和当前读行为不同，不能把 SELECT FOR UPDATE 等同于普通快照读。"],"follow":"用户翻页时保持事务很久有什么问题？","manual":true,"priority":false,"project":"通用","sourceDate":"2026-10-22","sourceRound":8,"sourceQuestion":2,"sourceRoundTitle":"读视图与长事务风险","referenceUrl":"https://dev.mysql.com/doc/refman/8.4/en/","answerMarkdown":"### 参考答案\n普通一致性读和当前读行为不同，不能把 SELECT FOR UPDATE 等同于普通快照读。\n\n### 易错点\n普通一致性读和当前读行为不同，不能把 SELECT FOR UPDATE 等同于普通快照读。\n\n### 继续追问\n用户翻页时保持事务很久有什么问题？"},{"id":"daily-2026-10-22-r08-q03","module":"MySQL","type":"场景题","title":"用户翻页时保持事务很久有什么问题？","prompt":"用户翻页时保持事务很久有什么问题？","promptMarkdown":"用户翻页时保持事务很久有什么问题？","answer":["长生命周期会保留资源和版本，业务通常用短事务及明确的游标一致性约定。"],"pitfalls":["普通一致性读和当前读行为不同，不能把 SELECT FOR UPDATE 等同于普通快照读。"],"follow":"用户翻页时保持事务很久有什么问题？","manual":true,"priority":false,"project":"通用","sourceDate":"2026-10-22","sourceRound":8,"sourceQuestion":3,"sourceRoundTitle":"读视图与长事务风险","referenceUrl":"https://dev.mysql.com/doc/refman/8.4/en/","answerMarkdown":"### 参考答案\n长生命周期会保留资源和版本，业务通常用短事务及明确的游标一致性约定。\n\n### 易错点\n普通一致性读和当前读行为不同，不能把 SELECT FOR UPDATE 等同于普通快照读。\n\n### 继续追问\n用户翻页时保持事务很久有什么问题？"},{"id":"daily-2026-10-22-r08-q04","module":"MySQL","type":"代码题","title":"读视图与长事务风险：动手练习","prompt":"在隔离数据库查看活跃 InnoDB 事务，解释持续时间与状态。","promptMarkdown":"在隔离数据库查看活跃 InnoDB 事务，解释持续时间与状态。","answer":["InnoDB 一致性读使用读视图决定版本可见性；隔离级别和语句类型影响视图使用。长事务可能拖延旧版本回收并增加历史版本负担。"],"pitfalls":["普通一致性读和当前读行为不同，不能把 SELECT FOR UPDATE 等同于普通快照读。"],"follow":"用户翻页时保持事务很久有什么问题？","manual":true,"priority":false,"project":"通用","sourceDate":"2026-10-22","sourceRound":8,"sourceQuestion":4,"sourceRoundTitle":"读视图与长事务风险","referenceUrl":"https://dev.mysql.com/doc/refman/8.4/en/","answerMarkdown":"### 参考答案\nInnoDB 一致性读使用读视图决定版本可见性；隔离级别和语句类型影响视图使用。长事务可能拖延旧版本回收并增加历史版本负担。\n\n### 易错点\n普通一致性读和当前读行为不同，不能把 SELECT FOR UPDATE 等同于普通快照读。\n\n### 示例\n```sql\nSELECT trx_id,trx_started,trx_state,trx_mysql_thread_id FROM information_schema.innodb_trx;\n```\n\n命令与配置用于隔离练习环境；先核对占位名称、权限、路径与工具版本。Docker 示例不代表已在你的服务中部署。\n\n### 继续追问\n用户翻页时保持事务很久有什么问题？"},{"id":"daily-2026-10-22-r08-q05","module":"MySQL","type":"场景题","title":"IM 历史消息翻页必须一直占用同一个事务吗？","prompt":"IM 历史消息翻页必须一直占用同一个事务吗？","promptMarkdown":"IM 历史消息翻页必须一直占用同一个事务吗？","answer":["通常不应跨用户停留长期持有事务；用稳定排序、游标与可接受的变化语义设计，必要时采用明确的快照方案。"],"pitfalls":["普通一致性读和当前读行为不同，不能把 SELECT FOR UPDATE 等同于普通快照读。"],"follow":"用户翻页时保持事务很久有什么问题？","manual":true,"priority":false,"project":"IM","sourceDate":"2026-10-22","sourceRound":8,"sourceQuestion":5,"sourceRoundTitle":"读视图与长事务风险","referenceUrl":"https://dev.mysql.com/doc/refman/8.4/en/","answerMarkdown":"### 参考答案\n通常不应跨用户停留长期持有事务；用稳定排序、游标与可接受的变化语义设计，必要时采用明确的快照方案。\n\n### 易错点\n普通一致性读和当前读行为不同，不能把 SELECT FOR UPDATE 等同于普通快照读。\n\n### 继续追问\n用户翻页时保持事务很久有什么问题？"},{"id":"daily-2026-10-22-r09-q01","module":"Redis","type":"概念题","title":"RDB、AOF 与可恢复边界：关键机制","prompt":"请解释RDB、AOF 与可恢复边界的关键机制和适用边界。","promptMarkdown":"请解释RDB、AOF 与可恢复边界的关键机制和适用边界。","answer":["RDB 保存时间点快照，AOF 记录写操作，实际数据丢失窗口取决于持久化与刷盘策略及故障方式。复制和持久化解决不同问题。"],"pitfalls":["误操作可复制，异步复制也存在窗口；还需明确恢复目标与备份策略。"],"follow":"Redis 重启后部分在线路由消失是否等于消息丢失？","manual":true,"priority":false,"project":"通用","sourceDate":"2026-10-22","sourceRound":9,"sourceQuestion":1,"sourceRoundTitle":"RDB、AOF 与可恢复边界","referenceUrl":"https://redis.io/docs/latest/","answerMarkdown":"### 参考答案\nRDB 保存时间点快照，AOF 记录写操作，实际数据丢失窗口取决于持久化与刷盘策略及故障方式。复制和持久化解决不同问题。\n\n### 易错点\n误操作可复制，异步复制也存在窗口；还需明确恢复目标与备份策略。\n\n### 继续追问\nRedis 重启后部分在线路由消失是否等于消息丢失？"},{"id":"daily-2026-10-22-r09-q02","module":"Redis","type":"概念题","title":"有主从复制就一定不用持久化和备份吗？","prompt":"有主从复制就一定不用持久化和备份吗？","promptMarkdown":"有主从复制就一定不用持久化和备份吗？","answer":["误操作可复制，异步复制也存在窗口；还需明确恢复目标与备份策略。"],"pitfalls":["误操作可复制，异步复制也存在窗口；还需明确恢复目标与备份策略。"],"follow":"Redis 重启后部分在线路由消失是否等于消息丢失？","manual":true,"priority":false,"project":"通用","sourceDate":"2026-10-22","sourceRound":9,"sourceQuestion":2,"sourceRoundTitle":"RDB、AOF 与可恢复边界","referenceUrl":"https://redis.io/docs/latest/","answerMarkdown":"### 参考答案\n误操作可复制，异步复制也存在窗口；还需明确恢复目标与备份策略。\n\n### 易错点\n误操作可复制，异步复制也存在窗口；还需明确恢复目标与备份策略。\n\n### 继续追问\nRedis 重启后部分在线路由消失是否等于消息丢失？"},{"id":"daily-2026-10-22-r09-q03","module":"Redis","type":"场景题","title":"Redis 重启后部分在线路由消失是否等于消息丢失？","prompt":"Redis 重启后部分在线路由消失是否等于消息丢失？","promptMarkdown":"Redis 重启后部分在线路由消失是否等于消息丢失？","answer":["先按数据类别判断：路由可重建，消息事实应有可靠来源；不能把所有键统一看待。"],"pitfalls":["误操作可复制，异步复制也存在窗口；还需明确恢复目标与备份策略。"],"follow":"Redis 重启后部分在线路由消失是否等于消息丢失？","manual":true,"priority":false,"project":"通用","sourceDate":"2026-10-22","sourceRound":9,"sourceQuestion":3,"sourceRoundTitle":"RDB、AOF 与可恢复边界","referenceUrl":"https://redis.io/docs/latest/","answerMarkdown":"### 参考答案\n先按数据类别判断：路由可重建，消息事实应有可靠来源；不能把所有键统一看待。\n\n### 易错点\n误操作可复制，异步复制也存在窗口；还需明确恢复目标与备份策略。\n\n### 继续追问\nRedis 重启后部分在线路由消失是否等于消息丢失？"},{"id":"daily-2026-10-22-r09-q04","module":"Redis","type":"代码题","title":"RDB、AOF 与可恢复边界：动手练习","prompt":"只读检查隔离实例的持久化状态，避免直接修改配置。","promptMarkdown":"只读检查隔离实例的持久化状态，避免直接修改配置。","answer":["RDB 保存时间点快照，AOF 记录写操作，实际数据丢失窗口取决于持久化与刷盘策略及故障方式。复制和持久化解决不同问题。"],"pitfalls":["误操作可复制，异步复制也存在窗口；还需明确恢复目标与备份策略。"],"follow":"Redis 重启后部分在线路由消失是否等于消息丢失？","manual":true,"priority":false,"project":"通用","sourceDate":"2026-10-22","sourceRound":9,"sourceQuestion":4,"sourceRoundTitle":"RDB、AOF 与可恢复边界","referenceUrl":"https://redis.io/docs/latest/","answerMarkdown":"### 参考答案\nRDB 保存时间点快照，AOF 记录写操作，实际数据丢失窗口取决于持久化与刷盘策略及故障方式。复制和持久化解决不同问题。\n\n### 易错点\n误操作可复制，异步复制也存在窗口；还需明确恢复目标与备份策略。\n\n### 示例\n```redis\nINFO persistence\nINFO replication\n```\n\n命令与配置用于隔离练习环境；先核对占位名称、权限、路径与工具版本。Docker 示例不代表已在你的服务中部署。\n\n### 继续追问\nRedis 重启后部分在线路由消失是否等于消息丢失？"},{"id":"daily-2026-10-22-r09-q05","module":"Redis","type":"场景题","title":"IM 哪些 Redis 数据可以重建，哪些需额外保障？","prompt":"IM 哪些 Redis 数据可以重建，哪些需额外保障？","promptMarkdown":"IM 哪些 Redis 数据可以重建，哪些需额外保障？","answer":["按会话、路由、缓存、离线队列和业务事实分别定义；关键消息是否可从 MySQL 补拉要以实现与验证为准。"],"pitfalls":["误操作可复制，异步复制也存在窗口；还需明确恢复目标与备份策略。"],"follow":"Redis 重启后部分在线路由消失是否等于消息丢失？","manual":true,"priority":false,"project":"IM","sourceDate":"2026-10-22","sourceRound":9,"sourceQuestion":5,"sourceRoundTitle":"RDB、AOF 与可恢复边界","referenceUrl":"https://redis.io/docs/latest/","answerMarkdown":"### 参考答案\n按会话、路由、缓存、离线队列和业务事实分别定义；关键消息是否可从 MySQL 补拉要以实现与验证为准。\n\n### 易错点\n误操作可复制，异步复制也存在窗口；还需明确恢复目标与备份策略。\n\n### 继续追问\nRedis 重启后部分在线路由消失是否等于消息丢失？"},{"id":"daily-2026-10-22-r10-q01","module":"Nginx","type":"概念题","title":"upstream 错误与 502 定位：关键机制","prompt":"请解释upstream 错误与 502 定位的关键机制和适用边界。","promptMarkdown":"请解释upstream 错误与 502 定位的关键机制和适用边界。","answer":["502 常见于代理连接失败、上游提前关闭或无效响应。应按请求时间对齐 error log、上游状态和后端进程，而非直接增大所有超时。"],"pitfalls":["超时常可表现为 504；错误码只是入口线索，具体原因依赖错误日志与阶段证据。"],"follow":"只有一个 IM 节点偶发 502，怎样缩小范围？","manual":true,"priority":false,"project":"通用","sourceDate":"2026-10-22","sourceRound":10,"sourceQuestion":1,"sourceRoundTitle":"upstream 错误与 502 定位","referenceUrl":"https://nginx.org/en/docs/","answerMarkdown":"### 参考答案\n502 常见于代理连接失败、上游提前关闭或无效响应。应按请求时间对齐 error log、上游状态和后端进程，而非直接增大所有超时。\n\n### 易错点\n超时常可表现为 504；错误码只是入口线索，具体原因依赖错误日志与阶段证据。\n\n### 继续追问\n只有一个 IM 节点偶发 502，怎样缩小范围？"},{"id":"daily-2026-10-22-r10-q02","module":"Nginx","type":"概念题","title":"502 一定表示后端执行太慢吗？","prompt":"502 一定表示后端执行太慢吗？","promptMarkdown":"502 一定表示后端执行太慢吗？","answer":["超时常可表现为 504；错误码只是入口线索，具体原因依赖错误日志与阶段证据。"],"pitfalls":["超时常可表现为 504；错误码只是入口线索，具体原因依赖错误日志与阶段证据。"],"follow":"只有一个 IM 节点偶发 502，怎样缩小范围？","manual":true,"priority":false,"project":"通用","sourceDate":"2026-10-22","sourceRound":10,"sourceQuestion":2,"sourceRoundTitle":"upstream 错误与 502 定位","referenceUrl":"https://nginx.org/en/docs/","answerMarkdown":"### 参考答案\n超时常可表现为 504；错误码只是入口线索，具体原因依赖错误日志与阶段证据。\n\n### 易错点\n超时常可表现为 504；错误码只是入口线索，具体原因依赖错误日志与阶段证据。\n\n### 继续追问\n只有一个 IM 节点偶发 502，怎样缩小范围？"},{"id":"daily-2026-10-22-r10-q03","module":"Nginx","type":"场景题","title":"只有一个 IM 节点偶发 502，怎样缩小范围？","prompt":"只有一个 IM 节点偶发 502，怎样缩小范围？","promptMarkdown":"只有一个 IM 节点偶发 502，怎样缩小范围？","answer":["记录 upstream_addr、connect/header/response 时间，按节点关联重启、fd、连接池与异常日志。"],"pitfalls":["超时常可表现为 504；错误码只是入口线索，具体原因依赖错误日志与阶段证据。"],"follow":"只有一个 IM 节点偶发 502，怎样缩小范围？","manual":true,"priority":false,"project":"通用","sourceDate":"2026-10-22","sourceRound":10,"sourceQuestion":3,"sourceRoundTitle":"upstream 错误与 502 定位","referenceUrl":"https://nginx.org/en/docs/","answerMarkdown":"### 参考答案\n记录 upstream_addr、connect/header/response 时间，按节点关联重启、fd、连接池与异常日志。\n\n### 易错点\n超时常可表现为 504；错误码只是入口线索，具体原因依赖错误日志与阶段证据。\n\n### 继续追问\n只有一个 IM 节点偶发 502，怎样缩小范围？"},{"id":"daily-2026-10-22-r10-q04","module":"Nginx","type":"代码题","title":"upstream 错误与 502 定位：动手练习","prompt":"写访问日志格式草案，将请求与上游地址和耗时关联。","promptMarkdown":"写访问日志格式草案，将请求与上游地址和耗时关联。","answer":["502 常见于代理连接失败、上游提前关闭或无效响应。应按请求时间对齐 error log、上游状态和后端进程，而非直接增大所有超时。"],"pitfalls":["超时常可表现为 504；错误码只是入口线索，具体原因依赖错误日志与阶段证据。"],"follow":"只有一个 IM 节点偶发 502，怎样缩小范围？","manual":true,"priority":false,"project":"通用","sourceDate":"2026-10-22","sourceRound":10,"sourceQuestion":4,"sourceRoundTitle":"upstream 错误与 502 定位","referenceUrl":"https://nginx.org/en/docs/","answerMarkdown":"### 参考答案\n502 常见于代理连接失败、上游提前关闭或无效响应。应按请求时间对齐 error log、上游状态和后端进程，而非直接增大所有超时。\n\n### 易错点\n超时常可表现为 504；错误码只是入口线索，具体原因依赖错误日志与阶段证据。\n\n### 示例\n```nginx\nlog_format lab '$request_id $status $upstream_addr $upstream_status $upstream_connect_time $upstream_response_time';\n```\n\n命令与配置用于隔离练习环境；先核对占位名称、权限、路径与工具版本。Docker 示例不代表已在你的服务中部署。\n\n### 继续追问\n只有一个 IM 节点偶发 502，怎样缩小范围？"},{"id":"daily-2026-10-22-r10-q05","module":"Nginx","type":"场景题","title":"IM 排障日志应该保留 Token 吗？","prompt":"IM 排障日志应该保留 Token 吗？","promptMarkdown":"IM 排障日志应该保留 Token 吗？","answer":["用独立请求关联 ID、节点和阶段错误描述定位，不记录完整 Token；代理与应用需使用可关联且可信的标识。"],"pitfalls":["超时常可表现为 504；错误码只是入口线索，具体原因依赖错误日志与阶段证据。"],"follow":"只有一个 IM 节点偶发 502，怎样缩小范围？","manual":true,"priority":false,"project":"IM","sourceDate":"2026-10-22","sourceRound":10,"sourceQuestion":5,"sourceRoundTitle":"upstream 错误与 502 定位","referenceUrl":"https://nginx.org/en/docs/","answerMarkdown":"### 参考答案\n用独立请求关联 ID、节点和阶段错误描述定位，不记录完整 Token；代理与应用需使用可关联且可信的标识。\n\n### 易错点\n超时常可表现为 504；错误码只是入口线索，具体原因依赖错误日志与阶段证据。\n\n### 继续追问\n只有一个 IM 节点偶发 502，怎样缩小范围？"},{"id":"daily-2026-10-22-r11-q01","module":"项目追问","type":"概念题","title":"IM：路由代际与陈旧回调：关键机制","prompt":"请解释IM：路由代际与陈旧回调的关键机制和适用边界。","promptMarkdown":"请解释IM：路由代际与陈旧回调的关键机制和适用边界。","answer":["用户重连到新节点后，旧连接的延迟清理不能删除新路由。路由值应带会话代际或唯一会话标识，清理时比较后再删除。"],"pitfalls":["可能删除新节点刚写入的路由；需要校验当前值仍属于旧会话。"],"follow":"重连成功后短暂收不到消息，怎么复现旧回调竞争？","manual":true,"priority":false,"project":"IM","sourceDate":"2026-10-22","sourceRound":11,"sourceQuestion":1,"sourceRoundTitle":"IM：路由代际与陈旧回调","referenceUrl":"https://github.com/qzshen219-pixel/im-system","answerMarkdown":"### 参考答案\n用户重连到新节点后，旧连接的延迟清理不能删除新路由。路由值应带会话代际或唯一会话标识，清理时比较后再删除。\n\n### 易错点\n可能删除新节点刚写入的路由；需要校验当前值仍属于旧会话。\n\n### 继续追问\n重连成功后短暂收不到消息，怎么复现旧回调竞争？"},{"id":"daily-2026-10-22-r11-q02","module":"项目追问","type":"概念题","title":"旧节点断线时直接 DEL 用户路由安全吗？","prompt":"旧节点断线时直接 DEL 用户路由安全吗？","promptMarkdown":"旧节点断线时直接 DEL 用户路由安全吗？","answer":["可能删除新节点刚写入的路由；需要校验当前值仍属于旧会话。"],"pitfalls":["可能删除新节点刚写入的路由；需要校验当前值仍属于旧会话。"],"follow":"重连成功后短暂收不到消息，怎么复现旧回调竞争？","manual":true,"priority":false,"project":"IM","sourceDate":"2026-10-22","sourceRound":11,"sourceQuestion":2,"sourceRoundTitle":"IM：路由代际与陈旧回调","referenceUrl":"https://github.com/qzshen219-pixel/im-system","answerMarkdown":"### 参考答案\n可能删除新节点刚写入的路由；需要校验当前值仍属于旧会话。\n\n### 易错点\n可能删除新节点刚写入的路由；需要校验当前值仍属于旧会话。\n\n### 继续追问\n重连成功后短暂收不到消息，怎么复现旧回调竞争？"},{"id":"daily-2026-10-22-r11-q03","module":"项目追问","type":"场景题","title":"重连成功后短暂收不到消息，怎么复现旧回调竞争？","prompt":"重连成功后短暂收不到消息，怎么复现旧回调竞争？","promptMarkdown":"重连成功后短暂收不到消息，怎么复现旧回调竞争？","answer":["人为延迟旧连接清理，先写新路由再触发旧清理，核对新映射是否被误删。"],"pitfalls":["可能删除新节点刚写入的路由；需要校验当前值仍属于旧会话。"],"follow":"重连成功后短暂收不到消息，怎么复现旧回调竞争？","manual":true,"priority":false,"project":"IM","sourceDate":"2026-10-22","sourceRound":11,"sourceQuestion":3,"sourceRoundTitle":"IM：路由代际与陈旧回调","referenceUrl":"https://github.com/qzshen219-pixel/im-system","answerMarkdown":"### 参考答案\n人为延迟旧连接清理，先写新路由再触发旧清理，核对新映射是否被误删。\n\n### 易错点\n可能删除新节点刚写入的路由；需要校验当前值仍属于旧会话。\n\n### 继续追问\n重连成功后短暂收不到消息，怎么复现旧回调竞争？"},{"id":"daily-2026-10-22-r11-q04","module":"项目追问","type":"代码题","title":"IM：路由代际与陈旧回调：动手练习","prompt":"写比较后删除的 Lua 草案，仅作用于隔离测试键。","promptMarkdown":"写比较后删除的 Lua 草案，仅作用于隔离测试键。","answer":["用户重连到新节点后，旧连接的延迟清理不能删除新路由。路由值应带会话代际或唯一会话标识，清理时比较后再删除。"],"pitfalls":["可能删除新节点刚写入的路由；需要校验当前值仍属于旧会话。"],"follow":"重连成功后短暂收不到消息，怎么复现旧回调竞争？","manual":true,"priority":false,"project":"IM","sourceDate":"2026-10-22","sourceRound":11,"sourceQuestion":4,"sourceRoundTitle":"IM：路由代际与陈旧回调","referenceUrl":"https://github.com/qzshen219-pixel/im-system","answerMarkdown":"### 参考答案\n用户重连到新节点后，旧连接的延迟清理不能删除新路由。路由值应带会话代际或唯一会话标识，清理时比较后再删除。\n\n### 易错点\n可能删除新节点刚写入的路由；需要校验当前值仍属于旧会话。\n\n### 示例\n```lua\nif redis.call('GET', KEYS[1]) == ARGV[1] then\n return redis.call('DEL', KEYS[1])\nend\nreturn 0\n```\n\n命令与配置用于隔离练习环境；先核对占位名称、权限、路径与工具版本。Docker 示例不代表已在你的服务中部署。\n\n### 继续追问\n重连成功后短暂收不到消息，怎么复现旧回调竞争？"},{"id":"daily-2026-10-22-r11-q05","module":"项目追问","type":"场景题","title":"IM 路由的 TTL 能完全替代代际比较吗？","prompt":"IM 路由的 TTL 能完全替代代际比较吗？","promptMarkdown":"IM 路由的 TTL 能完全替代代际比较吗？","answer":["TTL 限制陈旧状态寿命，但不阻止旧清理误删新值；续期和删除都要核对所有者。"],"pitfalls":["可能删除新节点刚写入的路由；需要校验当前值仍属于旧会话。"],"follow":"重连成功后短暂收不到消息，怎么复现旧回调竞争？","manual":true,"priority":false,"project":"IM","sourceDate":"2026-10-22","sourceRound":11,"sourceQuestion":5,"sourceRoundTitle":"IM：路由代际与陈旧回调","referenceUrl":"https://github.com/qzshen219-pixel/im-system","answerMarkdown":"### 参考答案\nTTL 限制陈旧状态寿命，但不阻止旧清理误删新值；续期和删除都要核对所有者。\n\n### 易错点\n可能删除新节点刚写入的路由；需要校验当前值仍属于旧会话。\n\n### 继续追问\n重连成功后短暂收不到消息，怎么复现旧回调竞争？"},{"id":"daily-2026-10-22-r12-q01","module":"项目追问","type":"概念题","title":"云盘：删除状态与恢复闭环：关键机制","prompt":"请解释云盘：删除状态与恢复闭环的关键机制和适用边界。","promptMarkdown":"请解释云盘：删除状态与恢复闭环的关键机制和适用边界。","answer":["状态标记把用户可见性和物理清理阶段分开；active→deleting 后再删内容，最终记为 deleted 或失败状态。状态机仍需定义崩溃恢复。"],"pitfalls":["还需扫描、重试、幂等、告警与终止策略；状态字段不是自动执行器。"],"follow":"物理文件已删但数据库更新失败，重试应怎样处理？","manual":true,"priority":false,"project":"云盘","sourceDate":"2026-10-22","sourceRound":12,"sourceQuestion":1,"sourceRoundTitle":"云盘：删除状态与恢复闭环","referenceUrl":"https://github.com/qzshen219-pixel/distributed-cloud-disk","answerMarkdown":"### 参考答案\n状态标记把用户可见性和物理清理阶段分开；active→deleting 后再删内容，最终记为 deleted 或失败状态。状态机仍需定义崩溃恢复。\n\n### 易错点\n还需扫描、重试、幂等、告警与终止策略；状态字段不是自动执行器。\n\n### 继续追问\n物理文件已删但数据库更新失败，重试应怎样处理？"},{"id":"daily-2026-10-22-r12-q02","module":"项目追问","type":"概念题","title":"有 deleting 字段就能自动恢复任何删除失败吗？","prompt":"有 deleting 字段就能自动恢复任何删除失败吗？","promptMarkdown":"有 deleting 字段就能自动恢复任何删除失败吗？","answer":["还需扫描、重试、幂等、告警与终止策略；状态字段不是自动执行器。"],"pitfalls":["还需扫描、重试、幂等、告警与终止策略；状态字段不是自动执行器。"],"follow":"物理文件已删但数据库更新失败，重试应怎样处理？","manual":true,"priority":false,"project":"云盘","sourceDate":"2026-10-22","sourceRound":12,"sourceQuestion":2,"sourceRoundTitle":"云盘：删除状态与恢复闭环","referenceUrl":"https://github.com/qzshen219-pixel/distributed-cloud-disk","answerMarkdown":"### 参考答案\n还需扫描、重试、幂等、告警与终止策略；状态字段不是自动执行器。\n\n### 易错点\n还需扫描、重试、幂等、告警与终止策略；状态字段不是自动执行器。\n\n### 继续追问\n物理文件已删但数据库更新失败，重试应怎样处理？"},{"id":"daily-2026-10-22-r12-q03","module":"项目追问","type":"场景题","title":"物理文件已删但数据库更新失败，重试应怎样处理？","prompt":"物理文件已删但数据库更新失败，重试应怎样处理？","promptMarkdown":"物理文件已删但数据库更新失败，重试应怎样处理？","answer":["区分对象已不存在与真实存储故障，在所有权和状态校验后让重复清理收敛到完成。"],"pitfalls":["还需扫描、重试、幂等、告警与终止策略；状态字段不是自动执行器。"],"follow":"物理文件已删但数据库更新失败，重试应怎样处理？","manual":true,"priority":false,"project":"云盘","sourceDate":"2026-10-22","sourceRound":12,"sourceQuestion":3,"sourceRoundTitle":"云盘：删除状态与恢复闭环","referenceUrl":"https://github.com/qzshen219-pixel/distributed-cloud-disk","answerMarkdown":"### 参考答案\n区分对象已不存在与真实存储故障，在所有权和状态校验后让重复清理收敛到完成。\n\n### 易错点\n还需扫描、重试、幂等、告警与终止策略；状态字段不是自动执行器。\n\n### 继续追问\n物理文件已删但数据库更新失败，重试应怎样处理？"},{"id":"daily-2026-10-22-r12-q04","module":"项目追问","type":"代码题","title":"云盘：删除状态与恢复闭环：动手练习","prompt":"只读查找停留在删除过程中的测试记录，说明后续恢复决策。","promptMarkdown":"只读查找停留在删除过程中的测试记录，说明后续恢复决策。","answer":["状态标记把用户可见性和物理清理阶段分开；active→deleting 后再删内容，最终记为 deleted 或失败状态。状态机仍需定义崩溃恢复。"],"pitfalls":["还需扫描、重试、幂等、告警与终止策略；状态字段不是自动执行器。"],"follow":"物理文件已删但数据库更新失败，重试应怎样处理？","manual":true,"priority":false,"project":"云盘","sourceDate":"2026-10-22","sourceRound":12,"sourceQuestion":4,"sourceRoundTitle":"云盘：删除状态与恢复闭环","referenceUrl":"https://github.com/qzshen219-pixel/distributed-cloud-disk","answerMarkdown":"### 参考答案\n状态标记把用户可见性和物理清理阶段分开；active→deleting 后再删内容，最终记为 deleted 或失败状态。状态机仍需定义崩溃恢复。\n\n### 易错点\n还需扫描、重试、幂等、告警与终止策略；状态字段不是自动执行器。\n\n### 示例\n```sql\nSELECT id,storage_type,status FROM files WHERE status IN ('deleting','delete_failed');\n```\n\n命令与配置用于隔离练习环境；先核对占位名称、权限、路径与工具版本。Docker 示例不代表已在你的服务中部署。\n\n### 继续追问\n物理文件已删但数据库更新失败，重试应怎样处理？"},{"id":"daily-2026-10-22-r12-q05","module":"项目追问","type":"场景题","title":"云盘如何验证并发删除不会让文件状态倒退？","prompt":"云盘如何验证并发删除不会让文件状态倒退？","promptMarkdown":"云盘如何验证并发删除不会让文件状态倒退？","answer":["并发领取用条件更新或等价控制，重复执行检查最终状态；测试删除后分享、下载与列表均遵守可见性约定。"],"pitfalls":["还需扫描、重试、幂等、告警与终止策略；状态字段不是自动执行器。"],"follow":"物理文件已删但数据库更新失败，重试应怎样处理？","manual":true,"priority":false,"project":"云盘","sourceDate":"2026-10-22","sourceRound":12,"sourceQuestion":5,"sourceRoundTitle":"云盘：删除状态与恢复闭环","referenceUrl":"https://github.com/qzshen219-pixel/distributed-cloud-disk","answerMarkdown":"### 参考答案\n并发领取用条件更新或等价控制，重复执行检查最终状态；测试删除后分享、下载与列表均遵守可见性约定。\n\n### 易错点\n还需扫描、重试、幂等、告警与终止策略；状态字段不是自动执行器。\n\n### 继续追问\n物理文件已删但数据库更新失败，重试应怎样处理？"}];const ids=new Set(window.QUESTION_BANK.map(q=>q.id));for(const q of added){if(!ids.has(q.id)){window.QUESTION_BANK.push(q);ids.add(q.id);}}})();
